<section class="section"><h1><?= esc($job['summary']) ?></h1><p><?= esc(\Config\VehicleDamage::WORK_INTENTS[$job['intent_code']]) ?> · <?= esc(\Config\VehicleDamage::WORK_CATEGORIES[$job['category_code']]) ?> · <strong><?= esc(\Config\VehicleDamage::WORK_STATUSES[$job['status_code']]) ?></strong></p>
