<details class="capital-disclosure"><summary>Schedule / reschedule</summary><form action="<?= $base ?>/schedule" method="post"><?= csrf_field() ?><?= view('vehicle_damage_repairs/_command', ['workAction' => 'schedule']) ?><label>Scheduled time<input type="datetime-local" name="scheduled_at" required value="<?= esc((string) ($formData['scheduled_at'] ?? ''), 'attr') ?>"></label><button type="submit">Save schedule</button></form></details>
