<?php endif; ?>
<?php if (in_array($job['status_code'], ['planned', 'scheduled', 'in_progress'], true)): ?><details class="capital-disclosure"><summary>Defer work</summary><form action="<?= $base ?>/defer" method="post"><?= csrf_field() ?><?= view('vehicle_damage_repairs/_command', ['workAction' => 'defer']) ?><label>Reason<textarea name="reason" required maxlength="2000"><?= esc((string) ($formData['reason'] ?? '')) ?></textarea></label><button type="submit">Defer</button></form></details><?php endif; ?>
<?php if ($job['status_code'] === 'deferred'): ?><details class="capital-disclosure"><summary>Resume work</summary><form action="<?= $base ?>/resume" method="post"><?= csrf_field() ?><?= view('vehicle_damage_repairs/_command', ['workAction' => 'resume']) ?><label>Resume as<select name="target_status"><option value="planned">Planned</option><option value="scheduled">Scheduled</option><option value="in_progress">In progress</option></select></label><label>Schedule time (if scheduled)<input type="datetime-local" name="scheduled_at"></label><label>Actual start (if not previously started)<input type="datetime-local" name="started_at"></label><label>Reason<textarea name="reason" required maxlength="2000"><?= esc((string) ($formData['reason'] ?? '')) ?></textarea></label><button type="submit">Resume</button></form></details><?php endif; ?>
<?php if (! $terminal): ?><details class="capital-disclosure"><summary>Cancel work</summary><form action="<?= $base ?>/cancel" method="post"><?= csrf_field() ?><?= view('vehicle_damage_repairs/_command', ['workAction' => 'cancel']) ?><label>Cancellation reason<textarea name="reason" required maxlength="2000"><?= esc((string) ($formData['reason'] ?? '')) ?></textarea></label><button type="submit">Cancel job</button></form></details><?php endif; ?>
<?php if (in_array($job['status_code'], ['in_progress', 'deferred'], true) && $job['started_at'] !== null): ?>
<details class="capital-disclosure"><summary>Complete work and record outcomes</summary><form action="<?= $base ?>/complete" method="post"><?= csrf_field() ?><?= view('vehicle_damage_repairs/_command', ['workAction' => 'complete']) ?>
<?php foreach ($activeMembers as $index => $m): $condition = $conditionsById[$m['vehicle_damage_item_id']]; $prefix = 'outcomes[' . $index . ']'; ?><fieldset><legend><?= esc($condition['description']) ?></legend><input type="hidden" name="<?= $prefix ?>[membership_id]" value="<?= (int) $m['id'] ?>"><input type="hidden" name="<?= $prefix ?>[expected_condition_state]" value="<?= esc($fingerprints[$condition['id']], 'attr') ?>">
