<label>Outcome / unassessed reason<textarea name="<?= $prefix ?>[note]" required maxlength="2000"><?= esc((string) ($formData['outcomes'][$index]['note'] ?? $m['note'] ?? '')) ?></textarea></label><label>Outcome time (optional)<input type="datetime-local" name="<?= $prefix ?>[occurred_at]" value="<?= esc((string) ($formData['outcomes'][$index]['occurred_at'] ?? ''), 'attr') ?>"></label></fieldset><?php endforeach; ?>
<label>Actual completion time<input type="datetime-local" name="completed_at" value="<?= esc((string) ($formData['completed_at'] ?? date('Y-m-d\TH:i')), 'attr') ?>"></label><label><input type="checkbox" name="completion_time_unknown" value="1"> Exact completion time is unknown (clear the time field)</label><label>Completion note<textarea name="completion_note" required maxlength="2000"><?= esc((string) ($formData['completion_note'] ?? '')) ?></textarea></label><p>Completing work does not confirm any physical condition repaired.</p><button type="submit">Complete job</button></form></details><?php endif; ?>
<?php if ($terminal): ?><details class="capital-disclosure"><summary>Reopen the same work order</summary><form action="<?= $base ?>/reopen" method="post"><?= csrf_field() ?><?= view('vehicle_damage_repairs/_command', ['workAction' => 'reopen_job']) ?><label>Reason category<select name="reason_category_code"><?php foreach (\Config\VehicleDamage::WORK_REOPEN_REASONS as $code => $label): if ($code === 'incorrect_cancellation' && $job['status_code'] !== 'cancelled') { continue; } ?><option value="<?= esc($code, 'attr') ?>"><?= esc($label) ?></option><?php endforeach; ?></select></label><label>Reason<textarea name="reason" required maxlength="2000"><?= esc((string) ($formData['reason'] ?? '')) ?></textarea></label><label><input type="checkbox" name="same_work_order_confirmed" value="1" required> This is the same continuing work order / effort.</label><p>A distinct later visit/order normally needs a new job. Physical conditions are not reopened here.</p><button type="submit">Reopen work job</button></form></details><?php endif; ?>
</div>
<?php if (! $terminal): ?><details class="capital-disclosure"><summary>Add / reactivate condition</summary><?php foreach ($vehicleDamage['current'] as $c): ?><form action="<?= $base ?>/conditions" method="post"><?= csrf_field() ?><?= view('vehicle_damage_repairs/_command', ['workAction' => 'add']) ?><input type="hidden" name="condition[selected_item_id]" value="<?= (int) $c['id'] ?>"><input type="hidden" name="condition[canonical_item_id]" value="<?= (int) $c['id'] ?>"><input type="hidden" name="condition[expected_condition_state]" value="<?= esc($fingerprints[$c['id']], 'attr') ?>"><label><input type="checkbox" name="condition[canonical_confirmed]" value="1" required> <?= esc($c['description']) ?></label><label>Scope change reason<textarea name="reason" required maxlength="2000"></textarea></label><button type="submit">Add / reactivate condition</button></form><?php endforeach; ?></details><?php endif; ?>
